import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const g=JSON.parse('{"title":"Schulinterne Funktionen für Lehrkräfte vorbereiten","description":"","frontmatter":{"title":"Schulinterne Funktionen für Lehrkräfte vorbereiten","source_pageid":1670,"source_revision":7207},"headers":[],"relativePath":"schild3/unterricht-kataloge/schulinterne-funktionen-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/schulinterne-funktionen-schulbezogene-kataloge.md"}'),o={name:"schild3/unterricht-kataloge/schulinterne-funktionen-schulbezogene-kataloge.md"};function a(l,e,u,s,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="schulinterne-funktionen-fur-lehrkrafte-vorbereiten" tabindex="-1">Schulinterne Funktionen für Lehrkräfte vorbereiten <a class="header-anchor" href="#schulinterne-funktionen-fur-lehrkrafte-vorbereiten" aria-label="Permalink to &quot;Schulinterne Funktionen für Lehrkräfte vorbereiten&quot;">​</a></h1><p>Definieren Sie die schulischen Funktionen im Katalog, bevor Sie diese Lehrkräften in den zeitabhängigen Daten zuweisen.</p><p>Unter <strong>Kataloge ➜ Schulinterne Funktionen</strong> legen Sie fest, welche dieser Funktionen Sie für Ihre Lehrkräfte an Ihrer Schule vergeben möchten.</p><p>Wurde eine schulinterne Funktion definiert, kann diese im Bereich <strong>Lehrkräfte ➜ Zeitabhängige Daten</strong> und dann im Reiter <strong>Schulinterne Funktionen</strong> mit einem Klick auf das <strong>Plus +</strong> zugewiesen werden.</p><p>Die Liste der Funktionen wird im Katalogbereich bearbeitet. Die individuelle Zuordnung erfolgt weiterhin bei den zeitabhängigen Lehrkräftedaten.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Schulinterne_Funktionen_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7207.</p>',7)])])}const f=n(o,[["render",a]]);export{g as __pageData,f as default};
